import { UserProfile, SectorKey } from '../types';

export interface YearlyProjection {
  year: number;
  totalAssets: number;
  nasdaqAssets: number;
  sp500Assets: number;
  annualInvestment: number;
  cumulativeInvestment: number;
}

export function runSimulation(profile: UserProfile): YearlyProjection[] {
  const {
    initialNasdaq,
    initialSP500,
    defaultCash,
    defaultVpoint,
    allocation,
    returnAssumptions,
    targetYears,
  } = profile;

  const monthlyTotal = defaultCash + defaultVpoint;
  const projections: YearlyProjection[] = [];

  let nasdaqAssets = initialNasdaq;
  let sp500Assets = initialSP500;
  let cumulativeInvestment = initialNasdaq + initialSP500;

  const nasdaqMonthlyRate = Math.pow(1 + returnAssumptions.nasdaq, 1 / 12) - 1;
  const sp500MonthlyRate = Math.pow(1 + returnAssumptions.sp500, 1 / 12) - 1;

  for (let y = 1; y <= Math.max(targetYears, 20); y++) {
    let annualInvestment = 0;

    for (let m = 1; m <= 12; m++) {
      const nasdaqContrib = monthlyTotal * (allocation.nasdaq / 100);
      const sp500Contrib = monthlyTotal * (allocation.sp500 / 100);
      annualInvestment += monthlyTotal;

      nasdaqAssets = nasdaqAssets * (1 + nasdaqMonthlyRate) + nasdaqContrib;
      sp500Assets = sp500Assets * (1 + sp500MonthlyRate) + sp500Contrib;
    }

    cumulativeInvestment += annualInvestment;

    projections.push({
      year: y,
      totalAssets: nasdaqAssets + sp500Assets,
      nasdaqAssets,
      sp500Assets,
      annualInvestment,
      cumulativeInvestment,
    });
  }

  return projections;
}

// 旧コードとの互換性のため sectorBreakdown を生成するラッパー
export function runSimulationWithBreakdown(profile: UserProfile) {
  return runSimulation(profile).map(p => ({
    ...p,
    sectorBreakdown: { nasdaq: p.nasdaqAssets, sp500: p.sp500Assets } as Record<SectorKey, number>,
  }));
}

export function formatCurrency(value: number): string {
  if (value >= 100000000) return `${(value / 100000000).toFixed(2)}億円`;
  if (value >= 10000000) return `${(value / 10000).toFixed(0)}万円`;
  return `${Math.round(value).toLocaleString()}円`;
}

export function formatCurrencyShort(value: number): string {
  if (value >= 100000000) return `${(value / 100000000).toFixed(1)}億`;
  if (value >= 10000) return `${(value / 10000).toFixed(0)}万`;
  return `${value.toLocaleString()}`;
}
