const DATA_URL = 'https://goof5592.github.io/investment-dashboard/data.json';

export interface InvestmentData {
  updated: number;
  etf: { price: number };
  ndx: { price: number };
  usdjpy: { price: number };
}

export interface TradeForSync {
  fund: string;
  sector: string;
  amount: number;
  price: number;
  units: number;
}

// NDX reference price key (per session, captured on first sync)
const NDX_REF_KEY = 'ndx_ref_price_v2';

export async function fetchInvestmentData(): Promise<InvestmentData> {
  const res = await fetch(DATA_URL);
  if (!res.ok) throw new Error(`データ取得失敗: ${res.status}`);
  return res.json();
}

// 2840 ETF価格からSBI NASDAQ-100の推定基準価額を算出するスケール
// 基準日: 2840=2,680円 のとき SBI NASDAQ-100 NAV=9,988円
const NAV_SCALE = 9988 / 2680;

export function calcPortfolioValue(data: InvestmentData, trades: TradeForSync[]): {
  ifNasValue: number;
  ifNasCost: number;
  ifNasGain: number;
  sbiNasValue: number;
  sbiNasCost: number;
  sbiNasGain: number;
  estimatedNAV: number;
  etfPrice: number;
  ndxPrice: number;
  updatedAt: Date;
  ifNasShares: number;
  sbiNasUnits: number;
} {
  const ifNasTrades  = trades.filter(t => t.fund.includes('2840') || t.fund.includes('iFナス'));
  const sbiNasTrades = trades.filter(t => t.sector === 'nasdaq' && !t.fund.includes('2840') && !t.fund.includes('iFナス'));

  const ifNasShares = ifNasTrades.reduce((s, t) => s + t.units, 0);
  const ifNasCost   = ifNasTrades.reduce((s, t) => s + t.amount, 0);
  const ifNasValue  = Math.round(ifNasShares * data.etf.price);

  // 推定基準価額 = 2840現在価格 × NAV_SCALE
  const estimatedNAV = data.etf.price * NAV_SCALE;
  const sbiNasUnits  = sbiNasTrades.reduce((s, t) => s + t.units, 0);
  const sbiNasCost   = sbiNasTrades.reduce((s, t) => s + t.amount, 0);
  // 口数がある取引は推定NAVで計算、口数0の取引(価格未入力)はコストベース
  const sbiNasFromUnits = sbiNasTrades
    .filter(t => t.units > 0)
    .reduce((s, t) => s + Math.round(t.units * estimatedNAV / 10000), 0);
  const sbiNasFromCost = sbiNasTrades
    .filter(t => t.units === 0)
    .reduce((s, t) => s + t.amount, 0);
  const sbiNasValue = sbiNasFromUnits + sbiNasFromCost;

  return {
    ifNasValue, ifNasCost, ifNasGain: ifNasValue - ifNasCost,
    sbiNasValue, sbiNasCost, sbiNasGain: sbiNasValue - sbiNasCost,
    estimatedNAV: Math.round(estimatedNAV),
    etfPrice: data.etf.price,
    ndxPrice: data.ndx.price,
    updatedAt: new Date(data.updated * 1000),
    ifNasShares, sbiNasUnits,
  };
}
