import { createClient } from '@supabase/supabase-js';
import { AppState, MonthlyRecord, UserProfile } from '../types';

const SUPABASE_URL = 'https://fcxrwbnlvctgqgmkibyo.supabase.co';
const SUPABASE_KEY = 'sb_publishable_OXbD7OHV2KOum6VlsK6TIg_QKoV-rHy';

export const supabase = createClient(SUPABASE_URL, SUPABASE_KEY);

export async function loadFromSupabase(): Promise<AppState | null> {
  try {
    const [profileRes, recordsRes] = await Promise.all([
      supabase.from('investment_profile').select('data').eq('id', 1).single(),
      supabase.from('investment_records').select('year, month, data').order('year').order('month'),
    ]);

    if (profileRes.error && profileRes.error.code !== 'PGRST116') throw profileRes.error;
    if (recordsRes.error) throw recordsRes.error;

    if (!profileRes.data) return null;

    const records: MonthlyRecord[] = (recordsRes.data ?? []).map((r: any) => ({
      year: r.year,
      month: r.month,
      ...r.data,
    }));

    return {
      profile: profileRes.data.data as UserProfile,
      records,
    };
  } catch (e) {
    console.error('Supabase load error:', e);
    return null;
  }
}

export async function saveProfileToSupabase(profile: UserProfile): Promise<void> {
  const { error } = await supabase
    .from('investment_profile')
    .upsert({ id: 1, data: profile, updated_at: new Date().toISOString() });
  if (error) console.error('Profile save error:', error);
}

export async function saveRecordToSupabase(record: MonthlyRecord): Promise<void> {
  const { year, month, ...data } = record;
  const { error } = await supabase
    .from('investment_records')
    .upsert({ year, month, data, updated_at: new Date().toISOString() }, { onConflict: 'year,month' });
  if (error) console.error('Record save error:', error);
}

export async function deleteRecordFromSupabase(year: number, month: number): Promise<void> {
  const { error } = await supabase
    .from('investment_records')
    .delete()
    .eq('year', year)
    .eq('month', month);
  if (error) console.error('Record delete error:', error);
}
