import { AppState, UserProfile, MonthlyRecord, SectorAllocation } from '../types';
import { RETURN_ASSUMPTIONS } from '../constants/sectors';

const STORAGE_KEY = 'core_satellite_app_v2';
const LEGACY_KEY = 'core_satellite_app';

const DEFAULT_PROFILE: UserProfile = {
  startDate: '2026-06-15',
  targetYears: 15,
  initialNasdaq: 0,
  initialSP500: 0,
  defaultCash: 5350,
  defaultVpoint: 21000,
  allocation: {
    nasdaq: 82,
    sp500: 18,
  },
  scenario: 'moderate',
  returnAssumptions: RETURN_ASSUMPTIONS.moderate,
  isSetupComplete: false,
};

// 旧フォーマットのレコードを新フォーマットに変換
function migrateRecord(rec: any): MonthlyRecord {
  const oldSectors = rec.actual?.sectors ?? {};
  const newSectors: SectorAllocation = {
    nasdaq: (oldSectors.core ?? 0) + (oldSectors.nasdaq ?? 0),
    sp500: oldSectors.sp500 ?? 0,
  };
  const oldPlanSectors = rec.plan?.sectors ?? {};
  const newPlanSectors: SectorAllocation = {
    nasdaq: (oldPlanSectors.core ?? 0) + (oldPlanSectors.nasdaq ?? 0),
    sp500: oldPlanSectors.sp500 ?? 0,
  };

  // tradesのsectorもマイグレーション
  const trades = (rec.actual?.trades ?? []).map((t: any) => ({
    ...t,
    sector: t.sector === 'core' ? 'nasdaq' : (t.sector ?? 'nasdaq'),
  }));

  return {
    year: rec.year,
    month: rec.month,
    plan: {
      cash: rec.plan?.cash ?? 0,
      vpoint: rec.plan?.vpoint ?? 0,
      sectors: newPlanSectors,
    },
    actual: {
      cash: rec.actual?.cash ?? 0,
      vpoint: rec.actual?.vpoint ?? 0,
      sectors: newSectors,
      portfolioValue: rec.actual?.portfolioValue ?? 0,
      nasdaqValue: rec.actual?.nasdaqValue,
      sp500Value: rec.actual?.sp500Value,
      trades,
    },
    notes: rec.notes ?? '',
  };
}

// 旧プロフィールを新プロフィールに変換
function migrateProfile(old: any): UserProfile {
  return {
    startDate: old.startDate ?? '2026-06-15',
    targetYears: old.targetYears ?? 15,
    initialNasdaq: old.initialNasdaq ?? old.initialInvestment ?? 0,
    initialSP500: old.initialSP500 ?? 0,
    defaultCash: old.defaultCash ?? 5350,
    defaultVpoint: old.defaultVpoint ?? 21000,
    allocation: {
      nasdaq: old.allocation?.nasdaq ?? old.allocation?.core ?? 82,
      sp500: old.allocation?.sp500 ?? 18,
    },
    scenario: old.scenario ?? 'moderate',
    returnAssumptions: RETURN_ASSUMPTIONS[old.scenario ?? 'moderate'],
    isSetupComplete: old.isSetupComplete ?? false,
  };
}

export function loadState(): AppState {
  try {
    // まず新フォーマットを試す
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) return JSON.parse(raw);

    // 旧フォーマットから移行
    const legacy = localStorage.getItem(LEGACY_KEY);
    if (legacy) {
      const old = JSON.parse(legacy);
      const migrated: AppState = {
        profile: migrateProfile(old.profile ?? {}),
        records: (old.records ?? []).map(migrateRecord),
      };
      saveState(migrated);
      return migrated;
    }
  } catch {
    // fall through
  }
  return { profile: DEFAULT_PROFILE, records: [] };
}

export function saveState(state: AppState): void {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
}

export function exportJSON(state: AppState): void {
  const blob = new Blob([JSON.stringify(state, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `investment_data_${new Date().toISOString().slice(0, 10)}.json`;
  a.click();
  URL.revokeObjectURL(url);
}

export function exportCSV(records: MonthlyRecord[]): void {
  const headers = ['年', '月', '計画現金', '計画Vポイント', '計画NASDAQ', '計画S&P500', '実績現金', '実績Vポイント', '実績NASDAQ', '実績S&P500', 'ポートフォリオ評価額', 'NASDAQ評価額', 'S&P500評価額', 'メモ'];
  const rows = records.map(r => [
    r.year, r.month,
    r.plan.cash, r.plan.vpoint,
    r.plan.sectors.nasdaq, r.plan.sectors.sp500,
    r.actual.cash, r.actual.vpoint,
    r.actual.sectors.nasdaq, r.actual.sectors.sp500,
    r.actual.portfolioValue,
    r.actual.nasdaqValue ?? '',
    r.actual.sp500Value ?? '',
    `"${r.notes}"`,
  ]);
  const csv = [headers, ...rows].map(row => row.join(',')).join('\n');
  const blob = new Blob(['﻿' + csv], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `investment_records_${new Date().toISOString().slice(0, 10)}.csv`;
  a.click();
  URL.revokeObjectURL(url);
}

export function importJSON(file: File): Promise<AppState> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = JSON.parse(e.target?.result as string);
        resolve(data);
      } catch {
        reject(new Error('無効なJSONファイルです'));
      }
    };
    reader.readAsText(file);
  });
}
