import React, { useState, useEffect } from 'react';
import { formatCurrency } from '../../utils/simulation';
import { PlusCircle, Trash2, TrendingUp, TrendingDown, AlertTriangle, CheckCircle } from 'lucide-react';

interface BoosterHolding {
  id: string;
  name: string;
  fundCode: string;
  purchaseDate: string;
  purchaseAmount: number;
  purchaseNav: number;
  currentNav: number;
  units: number;
  targetGainPct: number;
  stopLossPct: number;
}

interface RebalanceRecord {
  id: string;
  date: string;
  fundName: string;
  saleAmount: number;
  gainAmount: number;
  reinvestedTo: 'nasdaq' | 'sp500' | 'both';
  notes: string;
}

const STORAGE_KEY = 'booster_data_v1';

const PRESET_FUNDS = [
  { name: 'FANG+インデックス', fundCode: 'iFreeNEXT FANG+' },
  { name: 'MEGA10テクノロジー', fundCode: 'iFreeNEXT MEGA10' },
];

function loadData(): { holdings: BoosterHolding[]; records: RebalanceRecord[] } {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : { holdings: [], records: [] };
  } catch {
    return { holdings: [], records: [] };
  }
}

function saveData(data: { holdings: BoosterHolding[]; records: RebalanceRecord[] }) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
}

function newHolding(): BoosterHolding {
  return {
    id: `${Date.now()}`,
    name: 'FANG+インデックス',
    fundCode: 'iFreeNEXT FANG+',
    purchaseDate: new Date().toISOString().slice(0, 10),
    purchaseAmount: 50000,
    purchaseNav: 0,
    currentNav: 0,
    units: 0,
    targetGainPct: 50,
    stopLossPct: 30,
  };
}

export default function BoosterView() {
  const [data, setData] = useState(loadData);
  const [showAddHolding, setShowAddHolding] = useState(false);
  const [showAddRecord, setShowAddRecord] = useState(false);
  const [editForm, setEditForm] = useState<BoosterHolding>(newHolding());
  const [recordForm, setRecordForm] = useState<RebalanceRecord>({
    id: '', date: new Date().toISOString().slice(0, 10),
    fundName: '', saleAmount: 0, gainAmount: 0,
    reinvestedTo: 'nasdaq', notes: '',
  });

  useEffect(() => { saveData(data); }, [data]);

  const addHolding = () => {
    const h = { ...editForm, id: `${Date.now()}` };
    setData(d => ({ ...d, holdings: [...d.holdings, h] }));
    setEditForm(newHolding());
    setShowAddHolding(false);
  };

  const removeHolding = (id: string) => {
    if (window.confirm('この保有を削除しますか？')) {
      setData(d => ({ ...d, holdings: d.holdings.filter(h => h.id !== id) }));
    }
  };

  const updateCurrentNav = (id: string, nav: number) => {
    setData(d => ({
      ...d,
      holdings: d.holdings.map(h => h.id === id ? { ...h, currentNav: nav } : h),
    }));
  };

  const addRecord = () => {
    const r = { ...recordForm, id: `${Date.now()}` };
    setData(d => ({ ...d, records: [r, ...d.records] }));
    setRecordForm({ id: '', date: new Date().toISOString().slice(0, 10), fundName: '', saleAmount: 0, gainAmount: 0, reinvestedTo: 'nasdaq', notes: '' });
    setShowAddRecord(false);
  };

  const removeRecord = (id: string) => {
    setData(d => ({ ...d, records: d.records.filter(r => r.id !== id) }));
  };

  const totalInvested = data.holdings.reduce((s, h) => s + h.purchaseAmount, 0);
  const totalCurrentValue = data.holdings.reduce((s, h) => {
    if (!h.currentNav || !h.purchaseNav) return s + h.purchaseAmount;
    return s + h.units * h.currentNav / 10000;
  }, 0);
  const totalGain = totalCurrentValue - totalInvested;
  const totalReinvested = data.records.reduce((s, r) => s + r.saleAmount, 0);

  return (
    <div className="p-4 lg:p-6 pb-20 lg:pb-6 max-w-3xl mx-auto space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-xl font-bold text-white">短期ブースター追跡</h1>
          <p className="text-gray-500 text-xs mt-1">FANG+ / MEGA10 — 目標+50%売却、-30%損切り</p>
        </div>
      </div>

      {/* サマリー */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
        <div className="bg-gray-900 rounded-xl p-4 border border-gray-800">
          <p className="text-gray-400 text-xs mb-1">取得コスト合計</p>
          <p className="text-white font-bold text-lg">{formatCurrency(totalInvested)}</p>
        </div>
        <div className="bg-gray-900 rounded-xl p-4 border border-gray-800">
          <p className="text-gray-400 text-xs mb-1">現在評価額</p>
          <p className="text-white font-bold text-lg">{formatCurrency(totalCurrentValue)}</p>
        </div>
        <div className="bg-gray-900 rounded-xl p-4 border border-gray-800">
          <p className="text-gray-400 text-xs mb-1">含み損益</p>
          <p className={`font-bold text-lg ${totalGain >= 0 ? 'text-green-400' : 'text-red-400'}`}>
            {totalGain >= 0 ? '+' : ''}{formatCurrency(totalGain)}
          </p>
        </div>
        <div className="bg-gray-900 rounded-xl p-4 border border-gray-800">
          <p className="text-gray-400 text-xs mb-1">売却→再投資累計</p>
          <p className="text-white font-bold text-lg">{formatCurrency(totalReinvested)}</p>
        </div>
      </div>

      {/* 保有一覧 */}
      <div className="bg-gray-900 rounded-xl border border-gray-800">
        <div className="flex items-center justify-between p-4 border-b border-gray-800">
          <h2 className="text-white font-bold">保有ファンド</h2>
          <button onClick={() => setShowAddHolding(true)}
            className="flex items-center gap-1.5 px-3 py-1.5 bg-blue-600 text-white rounded-lg text-sm hover:bg-blue-700 transition-colors">
            <PlusCircle size={15} />追加
          </button>
        </div>

        {data.holdings.length === 0 ? (
          <div className="p-6 text-center text-gray-500 text-sm">
            保有ファンドを追加してください
          </div>
        ) : (
          <div className="divide-y divide-gray-800">
            {data.holdings.map(h => <HoldingCard key={h.id} holding={h} onRemove={() => removeHolding(h.id)} onUpdateNav={nav => updateCurrentNav(h.id, nav)} />)}
          </div>
        )}
      </div>

      {/* 保有追加フォーム */}
      {showAddHolding && (
        <div className="bg-gray-900 rounded-xl p-4 border border-yellow-700/50">
          <h2 className="text-white font-bold mb-4">保有を追加</h2>
          <div className="space-y-3">
            <div>
              <p className="text-gray-500 text-xs mb-1">ファンド</p>
              <select value={editForm.name}
                onChange={e => {
                  const preset = PRESET_FUNDS.find(f => f.name === e.target.value);
                  setEditForm(f => ({ ...f, name: e.target.value, fundCode: preset?.fundCode ?? '' }));
                }}
                className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white focus:outline-none focus:border-blue-500">
                {PRESET_FUNDS.map(f => <option key={f.name} value={f.name}>{f.name}</option>)}
              </select>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <p className="text-gray-500 text-xs mb-1">購入日</p>
                <input type="date" value={editForm.purchaseDate}
                  onChange={e => setEditForm(f => ({ ...f, purchaseDate: e.target.value }))}
                  className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white focus:outline-none focus:border-blue-500" />
              </div>
              <div>
                <p className="text-gray-500 text-xs mb-1">取得金額（円）</p>
                <input type="number" value={editForm.purchaseAmount || ''}
                  onChange={e => setEditForm(f => ({ ...f, purchaseAmount: Number(e.target.value) }))}
                  className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white text-right focus:outline-none focus:border-blue-500" />
              </div>
              <div>
                <p className="text-gray-500 text-xs mb-1">取得基準価額（円/万口）</p>
                <input type="number" value={editForm.purchaseNav || ''}
                  onChange={e => {
                    const nav = Number(e.target.value);
                    const units = nav > 0 ? Math.floor(editForm.purchaseAmount / nav * 10000) : 0;
                    setEditForm(f => ({ ...f, purchaseNav: nav, units }));
                  }}
                  className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white text-right focus:outline-none focus:border-blue-500" />
              </div>
              <div>
                <p className="text-gray-500 text-xs mb-1">口数（自動計算）</p>
                <input type="number" value={editForm.units || ''} readOnly
                  className="w-full bg-gray-700 border border-gray-600 rounded-lg px-3 py-2 text-gray-300 text-right" />
              </div>
              <div>
                <p className="text-gray-500 text-xs mb-1">売却目標（%）</p>
                <input type="number" value={editForm.targetGainPct}
                  onChange={e => setEditForm(f => ({ ...f, targetGainPct: Number(e.target.value) }))}
                  className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white text-right focus:outline-none focus:border-blue-500" />
              </div>
              <div>
                <p className="text-gray-500 text-xs mb-1">損切りライン（%）</p>
                <input type="number" value={editForm.stopLossPct}
                  onChange={e => setEditForm(f => ({ ...f, stopLossPct: Number(e.target.value) }))}
                  className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white text-right focus:outline-none focus:border-blue-500" />
              </div>
            </div>
          </div>
          <div className="flex gap-3 mt-4">
            <button onClick={() => setShowAddHolding(false)}
              className="flex-1 py-2 bg-gray-700 text-gray-300 rounded-lg text-sm hover:bg-gray-600">キャンセル</button>
            <button onClick={addHolding}
              className="flex-1 py-2 bg-blue-600 text-white rounded-lg text-sm hover:bg-blue-700">追加する</button>
          </div>
        </div>
      )}

      {/* 売却・再投資記録 */}
      <div className="bg-gray-900 rounded-xl border border-gray-800">
        <div className="flex items-center justify-between p-4 border-b border-gray-800">
          <h2 className="text-white font-bold">売却・再投資記録</h2>
          <button onClick={() => setShowAddRecord(true)}
            className="flex items-center gap-1.5 px-3 py-1.5 bg-green-700 text-white rounded-lg text-sm hover:bg-green-600 transition-colors">
            <PlusCircle size={15} />売却記録
          </button>
        </div>

        {data.records.length === 0 ? (
          <div className="p-6 text-center text-gray-500 text-sm">売却・再投資の記録がありません</div>
        ) : (
          <div className="divide-y divide-gray-800">
            {data.records.map(r => (
              <div key={r.id} className="p-4 flex items-start justify-between gap-4">
                <div className="flex-1">
                  <div className="flex items-center gap-2 mb-1">
                    <span className="text-gray-500 text-xs">{r.date}</span>
                    <span className="text-white text-sm font-medium">{r.fundName}</span>
                    <span className="text-xs px-2 py-0.5 rounded-full bg-green-900/50 text-green-400">売却</span>
                  </div>
                  <div className="flex gap-4 text-sm">
                    <span className="text-gray-300">売却額: <span className="text-white font-bold">{formatCurrency(r.saleAmount)}</span></span>
                    <span className={r.gainAmount >= 0 ? 'text-green-400' : 'text-red-400'}>
                      損益: {r.gainAmount >= 0 ? '+' : ''}{formatCurrency(r.gainAmount)}
                    </span>
                    <span className="text-gray-500 text-xs">
                      再投資先: {r.reinvestedTo === 'both' ? 'NASDAQ+S&P500' : r.reinvestedTo === 'nasdaq' ? 'NASDAQ' : 'S&P500'}
                    </span>
                  </div>
                  {r.notes && <p className="text-gray-500 text-xs mt-1">{r.notes}</p>}
                </div>
                <button onClick={() => removeRecord(r.id)} className="text-red-400 hover:text-red-300 shrink-0">
                  <Trash2 size={14} />
                </button>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* 売却記録フォーム */}
      {showAddRecord && (
        <div className="bg-gray-900 rounded-xl p-4 border border-green-700/50">
          <h2 className="text-white font-bold mb-4">売却・再投資を記録</h2>
          <div className="space-y-3">
            <div className="grid grid-cols-2 gap-3">
              <div>
                <p className="text-gray-500 text-xs mb-1">売却日</p>
                <input type="date" value={recordForm.date}
                  onChange={e => setRecordForm(f => ({ ...f, date: e.target.value }))}
                  className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white focus:outline-none focus:border-blue-500" />
              </div>
              <div>
                <p className="text-gray-500 text-xs mb-1">ファンド名</p>
                <select value={recordForm.fundName}
                  onChange={e => setRecordForm(f => ({ ...f, fundName: e.target.value }))}
                  className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white focus:outline-none focus:border-blue-500">
                  <option value="">選択...</option>
                  {PRESET_FUNDS.map(f => <option key={f.name} value={f.name}>{f.name}</option>)}
                </select>
              </div>
              <div>
                <p className="text-gray-500 text-xs mb-1">売却額（円）</p>
                <input type="number" value={recordForm.saleAmount || ''}
                  onChange={e => setRecordForm(f => ({ ...f, saleAmount: Number(e.target.value) }))}
                  className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white text-right focus:outline-none focus:border-blue-500" />
              </div>
              <div>
                <p className="text-gray-500 text-xs mb-1">損益（円）</p>
                <input type="number" value={recordForm.gainAmount || ''}
                  onChange={e => setRecordForm(f => ({ ...f, gainAmount: Number(e.target.value) }))}
                  className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white text-right focus:outline-none focus:border-blue-500" />
              </div>
            </div>
            <div>
              <p className="text-gray-500 text-xs mb-1">再投資先</p>
              <div className="flex gap-3">
                {(['nasdaq', 'sp500', 'both'] as const).map(t => (
                  <button key={t} onClick={() => setRecordForm(f => ({ ...f, reinvestedTo: t }))}
                    className={`px-4 py-1.5 rounded-lg text-sm transition-colors ${recordForm.reinvestedTo === t ? 'bg-blue-600 text-white' : 'bg-gray-700 text-gray-400 hover:bg-gray-600'}`}>
                    {t === 'nasdaq' ? 'NASDAQ' : t === 'sp500' ? 'S&P500' : '両方'}
                  </button>
                ))}
              </div>
            </div>
            <div>
              <p className="text-gray-500 text-xs mb-1">メモ</p>
              <input type="text" value={recordForm.notes}
                onChange={e => setRecordForm(f => ({ ...f, notes: e.target.value }))}
                placeholder="+52%達成で売却"
                className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white focus:outline-none focus:border-blue-500" />
            </div>
          </div>
          <div className="flex gap-3 mt-4">
            <button onClick={() => setShowAddRecord(false)}
              className="flex-1 py-2 bg-gray-700 text-gray-300 rounded-lg text-sm hover:bg-gray-600">キャンセル</button>
            <button onClick={addRecord}
              className="flex-1 py-2 bg-green-600 text-white rounded-lg text-sm hover:bg-green-700">記録する</button>
          </div>
        </div>
      )}
    </div>
  );
}

function HoldingCard({ holding: h, onRemove, onUpdateNav }: {
  holding: BoosterHolding;
  onRemove: () => void;
  onUpdateNav: (nav: number) => void;
}) {
  const hasNav = h.purchaseNav > 0 && h.currentNav > 0;
  const currentValue = hasNav ? h.units * h.currentNav / 10000 : h.purchaseAmount;
  const gainPct = hasNav ? ((h.currentNav - h.purchaseNav) / h.purchaseNav) * 100 : 0;
  const gainAmt = currentValue - h.purchaseAmount;

  const isSellSignal = gainPct >= h.targetGainPct;
  const isStopLoss = gainPct <= -h.stopLossPct;
  const progressPct = h.targetGainPct > 0 ? Math.min(100, Math.max(0, (gainPct / h.targetGainPct) * 100)) : 0;

  return (
    <div className="p-4">
      <div className="flex items-start justify-between mb-3">
        <div>
          <div className="flex items-center gap-2">
            <span className="text-white font-bold">{h.name}</span>
            {isSellSignal && (
              <span className="flex items-center gap-1 px-2 py-0.5 bg-green-900/50 text-green-400 text-xs rounded-full">
                <CheckCircle size={11} />売却シグナル
              </span>
            )}
            {isStopLoss && (
              <span className="flex items-center gap-1 px-2 py-0.5 bg-red-900/50 text-red-400 text-xs rounded-full">
                <AlertTriangle size={11} />損切りライン
              </span>
            )}
          </div>
          <p className="text-gray-500 text-xs mt-0.5">{h.purchaseDate}購入 / {formatCurrency(h.purchaseAmount)}</p>
        </div>
        <button onClick={onRemove} className="text-red-400 hover:text-red-300"><Trash2 size={15} /></button>
      </div>

      <div className="grid grid-cols-3 gap-3 mb-3 text-sm">
        <div>
          <p className="text-gray-500 text-xs">現在評価額</p>
          <p className="text-white font-bold">{formatCurrency(currentValue)}</p>
        </div>
        <div>
          <p className="text-gray-500 text-xs">含み損益</p>
          <p className={`font-bold ${gainAmt >= 0 ? 'text-green-400' : 'text-red-400'}`}>
            {gainAmt >= 0 ? '+' : ''}{formatCurrency(gainAmt)}
          </p>
        </div>
        <div>
          <p className="text-gray-500 text-xs">騰落率</p>
          <p className={`font-bold flex items-center gap-1 ${gainPct >= 0 ? 'text-green-400' : 'text-red-400'}`}>
            {gainPct >= 0 ? <TrendingUp size={14} /> : <TrendingDown size={14} />}
            {gainPct >= 0 ? '+' : ''}{gainPct.toFixed(1)}%
          </p>
        </div>
      </div>

      {/* 目標までの進捗 */}
      <div className="mb-3">
        <div className="flex justify-between text-xs mb-1">
          <span className="text-gray-500">売却目標まで</span>
          <span className={isSellSignal ? 'text-green-400 font-bold' : 'text-gray-400'}>
            {gainPct.toFixed(1)}% / +{h.targetGainPct}%
          </span>
        </div>
        <div className="h-2 bg-gray-700 rounded-full overflow-hidden">
          <div className={`h-full rounded-full transition-all ${isSellSignal ? 'bg-green-500' : isStopLoss ? 'bg-red-500' : 'bg-blue-500'}`}
            style={{ width: `${progressPct}%` }} />
        </div>
        <div className="flex justify-between text-xs mt-1 text-gray-600">
          <span>損切 -{h.stopLossPct}%</span>
          <span>目標 +{h.targetGainPct}%</span>
        </div>
      </div>

      {/* 現在基準価額の更新 */}
      <div className="flex items-center gap-2 mt-2">
        <p className="text-gray-500 text-xs shrink-0">現在基準価額（円/万口）</p>
        <input type="number" value={h.currentNav || ''}
          onChange={e => onUpdateNav(Number(e.target.value))}
          placeholder={h.purchaseNav ? `取得時 ${h.purchaseNav.toLocaleString()}` : '入力'}
          className="flex-1 bg-gray-800 border border-gray-700 rounded-lg px-3 py-1.5 text-white text-right text-sm focus:outline-none focus:border-blue-500" />
      </div>
    </div>
  );
}
