import React, { createContext, useContext, useReducer, useEffect, useState } from 'react';
import { AppState, UserProfile, MonthlyRecord } from '../types';
import { loadState, saveState } from '../utils/storage';
import { loadFromSupabase, saveProfileToSupabase, saveRecordToSupabase, deleteRecordFromSupabase } from '../utils/supabase';
import { RETURN_ASSUMPTIONS } from '../constants/sectors';

type Action =
  | { type: 'UPDATE_PROFILE'; payload: Partial<UserProfile> }
  | { type: 'COMPLETE_SETUP'; payload: UserProfile }
  | { type: 'UPSERT_RECORD'; payload: MonthlyRecord }
  | { type: 'DELETE_RECORD'; payload: { year: number; month: number } }
  | { type: 'IMPORT_STATE'; payload: AppState }
  | { type: 'UPDATE_SCENARIO'; payload: UserProfile['scenario'] }
  | { type: 'LOAD_STATE'; payload: AppState };

interface AppContextValue {
  state: AppState;
  dispatch: React.Dispatch<Action>;
  syncing: boolean;
}

function reducer(state: AppState, action: Action): AppState {
  switch (action.type) {
    case 'LOAD_STATE':
      return action.payload;
    case 'UPDATE_PROFILE':
      return { ...state, profile: { ...state.profile, ...action.payload } };
    case 'COMPLETE_SETUP':
      return { ...state, profile: { ...action.payload, isSetupComplete: true } };
    case 'UPSERT_RECORD': {
      const { year, month } = action.payload;
      const existing = state.records.findIndex(r => r.year === year && r.month === month);
      const records = existing >= 0
        ? state.records.map((r, i) => i === existing ? action.payload : r)
        : [...state.records, action.payload];
      return { ...state, records: records.sort((a, b) => a.year !== b.year ? a.year - b.year : a.month - b.month) };
    }
    case 'DELETE_RECORD':
      return {
        ...state,
        records: state.records.filter(r => !(r.year === action.payload.year && r.month === action.payload.month)),
      };
    case 'IMPORT_STATE':
      return action.payload;
    case 'UPDATE_SCENARIO': {
      const assumptions = RETURN_ASSUMPTIONS[action.payload];
      return {
        ...state,
        profile: { ...state.profile, scenario: action.payload, returnAssumptions: assumptions },
      };
    }
    default:
      return state;
  }
}

const AppContext = createContext<AppContextValue | null>(null);

export function AppProvider({ children }: { children: React.ReactNode }) {
  const [state, dispatch] = useReducer(reducer, loadState());
  const [syncing, setSyncing] = useState(true);
  const [initialized, setInitialized] = useState(false);

  // 起動時にSupabaseからロード
  useEffect(() => {
    loadFromSupabase().then(remoteState => {
      if (remoteState) {
        dispatch({ type: 'LOAD_STATE', payload: remoteState });
        saveState(remoteState); // ローカルにも同期
      }
      setSyncing(false);
      setInitialized(true);
    });
  }, []);

  // 状態変化時にSupabaseへ保存
  useEffect(() => {
    if (!initialized) return;
    saveState(state); // LocalStorageにも保存（オフライン対応）
    saveProfileToSupabase(state.profile);
  }, [state.profile, initialized]);

  // 初期化完了後のみ記録変更を検知
  const prevRecordsRef = React.useRef<MonthlyRecord[]>([]);
  useEffect(() => {
    if (!initialized) return;
    const prev = prevRecordsRef.current;
    const curr = state.records;

    // 追加・更新されたレコードを検出
    curr.forEach(r => {
      const p = prev.find(x => x.year === r.year && x.month === r.month);
      if (!p || JSON.stringify(p) !== JSON.stringify(r)) {
        saveRecordToSupabase(r);
      }
    });

    // 削除されたレコードを検出
    prev.forEach(r => {
      if (!curr.find(x => x.year === r.year && x.month === r.month)) {
        deleteRecordFromSupabase(r.year, r.month);
      }
    });

    prevRecordsRef.current = curr;
  }, [state.records, initialized]);

  return (
    <AppContext.Provider value={{ state, dispatch, syncing }}>
      {children}
    </AppContext.Provider>
  );
}

export function useApp() {
  const ctx = useContext(AppContext);
  if (!ctx) throw new Error('useApp must be used within AppProvider');
  return ctx;
}
