import React, { useState } from 'react';
import { AppProvider, useApp } from './context/AppContext';
import SetupWizard from './components/Setup/SetupWizard';
import Navigation, { TabId } from './components/Layout/Navigation';
import Dashboard from './components/Dashboard/Dashboard';
import MonthlyInput from './components/Input/MonthlyInput';
import HistoryView from './components/History/HistoryView';
import SimulationView from './components/Simulation/SimulationView';
import ReportView from './components/Report/ReportView';
import SettingsView from './components/Settings/SettingsView';
import HelpView from './components/Help/HelpView';
import BoosterView from './components/Booster/BoosterView';

function AppInner() {
  const { state, syncing } = useApp();
  const [tab, setTab] = useState<TabId>('dashboard');

  if (syncing) {
    return (
      <div className="min-h-screen bg-gray-950 flex items-center justify-center">
        <div className="text-center">
          <div className="w-10 h-10 border-2 border-blue-500 border-t-transparent rounded-full animate-spin mx-auto mb-4" />
          <p className="text-gray-400 text-sm">データを読み込み中...</p>
        </div>
      </div>
    );
  }

  if (!state.profile.isSetupComplete) {
    return <SetupWizard />;
  }

  return (
    <div className="flex min-h-screen bg-gray-950">
      <Navigation active={tab} onChange={setTab} />
      <main className="flex-1 overflow-y-auto">
        {tab === 'dashboard' && <Dashboard onNavigate={(t) => setTab(t as TabId)} />}
        {tab === 'input' && <MonthlyInput />}
        {tab === 'history' && <HistoryView />}
        {tab === 'simulation' && <SimulationView />}
        {tab === 'report' && <ReportView />}
        {tab === 'booster' && <BoosterView />}
        {tab === 'settings' && <SettingsView />}
        {tab === 'help' && <HelpView />}
      </main>
    </div>
  );
}

export default function App() {
  return (
    <AppProvider>
      <AppInner />
    </AppProvider>
  );
}
