import React, { useState, useMemo } from 'react';
import { useApp } from '../../context/AppContext';
import { MonthlyRecord, Trade, SectorKey, NisaType } from '../../types';
import { formatCurrency } from '../../utils/simulation';
import { PlusCircle, Trash2, BookmarkCheck, X } from 'lucide-react';

const FUNDS = [
  { id: 'ifNas',    label: 'iFナス100H無 (2840)',           sector: 'nasdaq' as SectorKey, isETF: true  },
  { id: 'sbiNas',   label: 'SBI NASDAQ-100インデックス',     sector: 'nasdaq' as SectorKey, isETF: false },
  { id: 'sbiSP500', label: 'SBI S&P500インデックス',         sector: 'sp500'  as SectorKey, isETF: false },
  { id: 'ivv',      label: 'iShares Core S&P500 ETF (IVV)', sector: 'sp500'  as SectorKey, isETF: true  },
];

const NISA_COLORS: Record<NisaType, string> = {
  tsumitate: 'bg-yellow-900/50 text-yellow-400',
  seichou:   'bg-orange-900/50 text-orange-400',
  none:      'bg-gray-700 text-gray-400',
};
const NISA_LABELS: Record<NisaType, string> = {
  tsumitate: '積立枠', seichou: '成長枠', none: 'NISA外',
};

function calcUnits(amount: number, price: number, isETF: boolean): number {
  if (price <= 0) return 0;
  return isETF ? Math.floor(amount / price) : Math.floor(amount / price * 10000);
}

function emptyTrade(date: string, fundId = 'sbiNas', amount = 0, paymentType: 'cash'|'vpoint' = 'cash', nisaType: NisaType = 'seichou'): Trade {
  const fund = FUNDS.find(f => f.id === fundId)!;
  return {
    id: `${Date.now()}-${Math.random().toString(36).slice(2)}`,
    date, fund: fund.label, sector: fund.sector,
    amount, price: 0, units: 0, paymentType, nisaType,
  };
}

export default function TradeLog() {
  const { state, dispatch } = useApp();
  const { records, profile } = state;
  const [showForm, setShowForm] = useState(false);
  const [formMode, setFormMode] = useState<'tsumitate' | 'manual'>('manual');

  const today = new Date().toISOString().slice(0, 10);
  const tsumitateList = profile.tsumitateList ?? (profile.tsumitate ? [profile.tsumitate] : []);

  const [trade, setTrade] = useState<Trade>(emptyTrade(today));

  // 全取引を日付降順で表示
  const allTrades = useMemo(() => {
    const list: (Trade & { year: number; month: number })[] = [];
    records.forEach(r => {
      (r.actual.trades ?? []).forEach(t => list.push({ ...t, year: r.year, month: r.month }));
    });
    return list.sort((a, b) => b.date.localeCompare(a.date));
  }, [records]);

  const openManual = () => {
    setTrade(emptyTrade(today));
    setFormMode('manual');
    setShowForm(true);
  };

  const openEdit = (t: Trade) => {
    setTrade({ ...t });
    setFormMode('manual');
    setShowForm(true);
  };

  const openTsumitate = (cfg: typeof tsumitateList[0]) => {
    setTrade(emptyTrade(today, cfg.fundId, cfg.amount, cfg.paymentType, 'tsumitate'));
    setFormMode('tsumitate');
    setShowForm(true);
  };

  const updateTrade = (patch: Partial<Trade>) => {
    setTrade(prev => {
      const next = { ...prev, ...patch };
      if (patch.fund) {
        const f = FUNDS.find(x => x.label === patch.fund || x.id === patch.fund);
        if (f) { next.fund = f.label; next.sector = f.sector; }
      }
      const f = FUNDS.find(x => x.label === next.fund);
      if (patch.amount !== undefined || patch.price !== undefined) {
        next.units = calcUnits(next.amount, next.price, f?.isETF ?? false);
      }
      return next;
    });
  };

  const saveTrade = () => {
    if (!trade.amount || !trade.date) return;
    const d = new Date(trade.date);
    const year = d.getFullYear();
    const month = d.getMonth() + 1;
    const existing = records.find(r => r.year === year && r.month === month);

    const trades = [...(existing?.actual.trades ?? [])];
    const idx = trades.findIndex(t => t.id === trade.id);
    if (idx >= 0) trades[idx] = trade; else trades.push(trade);

    const allTrades = trades;
    const cash  = allTrades.filter(t => t.paymentType === 'cash').reduce((s, t) => s + t.amount, 0);
    const vpoint = allTrades.filter(t => t.paymentType === 'vpoint').reduce((s, t) => s + t.amount, 0);
    const nasdaq = allTrades.filter(t => t.sector === 'nasdaq').reduce((s, t) => s + t.amount, 0);
    const sp500  = allTrades.filter(t => t.sector === 'sp500').reduce((s, t) => s + t.amount, 0);

    const record: MonthlyRecord = {
      year, month,
      plan: existing?.plan ?? { cash: 0, vpoint: 0, sectors: { nasdaq: 0, sp500: 0 } },
      actual: {
        ...(existing?.actual ?? { portfolioValue: 0 }),
        portfolioValue: 0, // 取引変更後は時価同期で再取得するまでリセット
        nasdaqValue: undefined,
        sp500Value: existing?.actual.sp500Value,
        cash, vpoint,
        sectors: { nasdaq, sp500 },
        trades: allTrades,
      },
      notes: existing?.notes ?? '',
    };
    dispatch({ type: 'UPSERT_RECORD', payload: record });
    setShowForm(false);
  };

  const deleteTrade = (t: Trade & { year: number; month: number }) => {
    if (!window.confirm('この取引を削除しますか？')) return;
    const rec = records.find(r => r.year === t.year && r.month === t.month)!;
    const trades = (rec.actual.trades ?? []).filter(x => x.id !== t.id);
    const cash  = trades.filter(x => x.paymentType === 'cash').reduce((s, x) => s + x.amount, 0);
    const vpoint = trades.filter(x => x.paymentType === 'vpoint').reduce((s, x) => s + x.amount, 0);
    const nasdaq = trades.filter(x => x.sector === 'nasdaq').reduce((s, x) => s + x.amount, 0);
    const sp500  = trades.filter(x => x.sector === 'sp500').reduce((s, x) => s + x.amount, 0);
    dispatch({
      type: 'UPSERT_RECORD',
      payload: { ...rec, actual: { ...rec.actual, cash, vpoint, sectors: { nasdaq, sp500 }, trades } },
    });
  };

  const fundId = (label: string) => FUNDS.find(f => f.label === label)?.id ?? '';
  const fundInfo = FUNDS.find(f => f.label === trade.fund) ?? FUNDS[1];

  return (
    <div className="p-4 lg:p-6 pb-20 lg:pb-6 max-w-2xl mx-auto">
      <div className="flex items-center justify-between mb-6">
        <h1 className="text-xl font-bold text-white">購入記録</h1>
        <div className="flex gap-2 flex-wrap justify-end">
          {tsumitateList.map((cfg, i) => (
            <button key={i} onClick={() => openTsumitate(cfg)}
              className="flex items-center gap-1.5 px-3 py-2 bg-yellow-600 text-white rounded-lg text-sm hover:bg-yellow-700 transition-colors">
              <BookmarkCheck size={15} />
              積立{tsumitateList.length > 1 ? `(${cfg.paymentType === 'vpoint' ? 'Vポイント' : 'カード'})` : 'を記録'}
            </button>
          ))}
          <button onClick={openManual}
            className="flex items-center gap-1.5 px-3 py-2 bg-blue-600 text-white rounded-lg text-sm hover:bg-blue-700 transition-colors">
            <PlusCircle size={15} />購入を追加
          </button>
        </div>
      </div>

      {/* 入力フォーム */}
      {showForm && (
        <div className="bg-gray-900 rounded-xl border border-gray-700 mb-6 p-4">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-white font-bold">
              {formMode === 'tsumitate' ? '📌 積立を記録' : '購入を追加'}
            </h2>
            <button onClick={() => setShowForm(false)} className="text-gray-400 hover:text-white"><X size={18} /></button>
          </div>

          <div className="space-y-3">
            <div className="grid grid-cols-2 gap-3">
              <div>
                <p className="text-gray-500 text-xs mb-1">約定日</p>
                <input type="date" value={trade.date}
                  onChange={e => updateTrade({ date: e.target.value })}
                  className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white focus:outline-none focus:border-blue-500" />
              </div>
              <div>
                <p className="text-gray-500 text-xs mb-1">ファンド</p>
                <select value={fundId(trade.fund)}
                  onChange={e => {
                    const f = FUNDS.find(x => x.id === e.target.value)!;
                    updateTrade({ fund: f.label, sector: f.sector });
                  }}
                  disabled={formMode === 'tsumitate'}
                  className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white focus:outline-none focus:border-blue-500 disabled:opacity-60">
                  {FUNDS.map(f => <option key={f.id} value={f.id}>{f.label}</option>)}
                </select>
              </div>
            </div>

            <div className="grid grid-cols-3 gap-3">
              <div>
                <p className="text-gray-500 text-xs mb-1">金額（円）</p>
                <input type="number" value={trade.amount || ''}
                  onChange={e => updateTrade({ amount: Number(e.target.value) })}
                  className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white text-right focus:outline-none focus:border-blue-500" />
              </div>
              <div>
                <p className="text-gray-500 text-xs mb-1">{fundInfo.isETF ? '単価（円/株）' : '基準価額（円/万口）'}</p>
                <input type="number" value={trade.price || ''}
                  onChange={e => updateTrade({ price: Number(e.target.value) })}
                  className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white text-right focus:outline-none focus:border-blue-500" />
              </div>
              <div>
                <p className="text-gray-500 text-xs mb-1">{fundInfo.isETF ? '株数' : '口数'}</p>
                <input type="number" value={trade.units || ''} readOnly
                  className="w-full bg-gray-700 border border-gray-600 rounded-lg px-3 py-2 text-gray-300 text-right" />
              </div>
            </div>

            <div className="flex gap-2 flex-wrap">
              <div className="flex gap-2">
                {(['cash', 'vpoint'] as const).map(p => (
                  <button key={p} onClick={() => updateTrade({ paymentType: p })}
                    disabled={formMode === 'tsumitate'}
                    className={`px-3 py-1.5 rounded-lg text-sm transition-colors disabled:opacity-60 ${trade.paymentType === p ? 'bg-blue-600 text-white' : 'bg-gray-700 text-gray-400'}`}>
                    {p === 'cash' ? '現金' : 'Vポイント'}
                  </button>
                ))}
              </div>
              <div className="w-px bg-gray-700 self-stretch" />
              <div className="flex gap-2">
                {(['tsumitate', 'seichou', 'none'] as NisaType[]).map(n => (
                  <button key={n} onClick={() => updateTrade({ nisaType: n })}
                    disabled={formMode === 'tsumitate'}
                    className={`px-3 py-1.5 rounded-lg text-sm transition-colors disabled:opacity-60 ${trade.nisaType === n
                      ? n === 'tsumitate' ? 'bg-yellow-600 text-white' : n === 'seichou' ? 'bg-orange-600 text-white' : 'bg-gray-600 text-white'
                      : 'bg-gray-700 text-gray-400'}`}>
                    {NISA_LABELS[n]}
                  </button>
                ))}
              </div>
            </div>

            <button onClick={saveTrade} disabled={!trade.amount}
              className="w-full py-2.5 bg-green-600 text-white rounded-lg font-bold hover:bg-green-700 disabled:opacity-40 transition-colors">
              保存する
            </button>
          </div>
        </div>
      )}

      {/* 積立設定サマリー */}
      {tsumitateList.length > 0 && !showForm && (
        <div className="bg-yellow-900/20 border border-yellow-700/50 rounded-xl p-3 mb-4 space-y-2">
          <p className="text-yellow-400 text-xs font-medium">📌 NISA積立（つみたて投資枠）</p>
          {tsumitateList.map((cfg, i) => {
            const fund = FUNDS.find(f => f.id === cfg.fundId);
            return (
              <div key={i} className="flex items-center justify-between">
                <p className="text-white text-sm">
                  {fund?.label} · {formatCurrency(cfg.amount)}
                  <span className="text-gray-400 ml-2 text-xs">（{cfg.paymentType === 'vpoint' ? 'Vポイント' : 'カード'}）</span>
                </p>
                <button onClick={() => openTsumitate(cfg)}
                  className="px-3 py-1 bg-yellow-600 text-white rounded-lg text-xs hover:bg-yellow-700 shrink-0 ml-3">
                  今月分を記録
                </button>
              </div>
            );
          })}
        </div>
      )}

      {/* 取引履歴 */}
      {allTrades.length === 0 ? (
        <div className="text-center py-16 text-gray-500">
          <p className="mb-3">購入記録がありません</p>
          <button onClick={openManual}
            className="px-6 py-2 bg-blue-600 text-white rounded-lg text-sm hover:bg-blue-700">
            最初の購入を記録する
          </button>
        </div>
      ) : (
        <div className="bg-gray-900 rounded-xl border border-gray-800 overflow-hidden">
          <div className="divide-y divide-gray-800">
            {allTrades.map(t => (
              <div key={t.id} className="flex items-center gap-3 p-4 hover:bg-gray-800/50 cursor-pointer transition-colors"
                onClick={() => openEdit(t)}>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-0.5 flex-wrap">
                    <span className="text-white text-sm font-medium truncate">{t.fund}</span>
                    {t.nisaType && t.nisaType !== 'none' && (
                      <span className={`text-xs px-2 py-0.5 rounded-full shrink-0 ${NISA_COLORS[t.nisaType]}`}>
                        {NISA_LABELS[t.nisaType]}
                      </span>
                    )}
                    <span className={`text-xs px-2 py-0.5 rounded-full shrink-0 ${t.sector === 'nasdaq' ? 'bg-blue-900/50 text-blue-400' : 'bg-green-900/50 text-green-400'}`}>
                      {t.sector === 'nasdaq' ? 'NASDAQ' : 'S&P500'}
                    </span>
                  </div>
                  <div className="flex gap-3 text-xs text-gray-500">
                    <span>{t.date}</span>
                    {t.units > 0 && <span>{t.units.toLocaleString()}{FUNDS.find(f => f.label === t.fund)?.isETF ? '株' : '口'}</span>}
                    <span className={t.paymentType === 'vpoint' ? 'text-yellow-500' : ''}>{t.paymentType === 'vpoint' ? 'Vポイント' : '現金'}</span>
                  </div>
                </div>
                <span className="text-white font-bold shrink-0">{formatCurrency(t.amount)}</span>
                <button onClick={e => { e.stopPropagation(); deleteTrade(t); }} className="text-red-400 hover:text-red-300 shrink-0">
                  <Trash2 size={14} />
                </button>
              </div>
            ))}
          </div>
          <div className="p-4 border-t border-gray-800 flex justify-between text-sm">
            <span className="text-gray-400">合計 {allTrades.length}件</span>
            <span className="text-white font-bold">{formatCurrency(allTrades.reduce((s, t) => s + t.amount, 0))}</span>
          </div>
        </div>
      )}
    </div>
  );
}
